/* Global Styles */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: Arial, sans-serif;
  line-height: 1.6;
  color: #333;
  background-color: #f9f9f9;
}

header {
  background-color: #007bff;
  color: #ffffff;
  padding: 1em;
  text-align: center;
}

nav {
  background-color: #333;
  padding: 0.5em;
  text-align: center;
}

nav a {
  color: #ffffff;
  text-decoration: none;
  margin: 0 1em;
}

main {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 2em;
}

footer {
  background-color: #333;
  color: #ffffff;
  padding: 1em;
  text-align: center;
  clear: both;
}

/* Accessibility */
.skip-link {
  position: absolute;
  top: -40px;
  left: 0;
  background-color: #007bff;
  color: #ffffff;
  padding: 0.5em;
  z-index: 1;
}

.skip-link:focus {
  top: 0;
}
```
